-- name: platform__commands_changeagent_1 :one
UPDATE control_plane.agents a SET name=$4,purpose=$5,role_description=$6,avatar_url=$7,runtime_key=$8,version=version+1,updated_at=clock_timestamp() WHERE a.organization_id=$1::uuid AND a.ref=$2 AND a.version=$3 AND a.system_key IS NULL RETURNING a.project_id::text,a.ref,a.name,a.purpose,a.role_description,a.avatar_url,a.state,a.enabled,a.version,a.created_at,a.updated_at
